    if(!a.isLocal){const sampled=a.netBuffer?.sample(now);if(sampled){a.netTarget=sampled;const t=sampled;a.x=t.x;a.y=t.y;a.z=t.z;a.yaw=t.yaw||0;a.vx=t.vx||0;a.vy=t.vy||0;a.vz=t.vz||0;a.anim=t.anim||'idle';a.zone=t.zone||a.zone||'island';a.homeOwnerId=t.homeOwnerId||null;a.rig.visible=a.zone===game.zone&&(a.zone!=='home'||a.homeOwnerId===game.homeOwnerId);a.rig.position.set(a.x,a.y,a.z);a.rig.rotation.y=a.yaw}}
