function resolveActorOverlap(a){for(const other of game.actors.values()){if(other===a||other.zone!==a.zone||other.homeOwnerId!==a.homeOwnerId)continue;const dx=a.x-other.x,dz=a.z-other.z,d=Math.hypot(dx,dz),min=a.radius+other.radius;if(d>0&&d<min){const push=(min-d)*.52;a.x+=dx/d*push;a.z+=dz/d*push;a.rig.position.x=a.x;a.rig.position.z=a.z}}}
function movePlayer(dt){const a=game.player;if(!a)return;const intent=gameplay.movementIntent(keys,joy,game.cameraYaw),pad=game.padButtons||{},sprint=gameplay.wantsSprint(keys,input,pad,intent),preset=game.cameraRig.cfg;if((a._activityUntil||0)>performance.now()){if(intent.strength>.16||input.jumpQueued){a._activityUntil=0;a._activityAnim=null}else{a.vx=gameplay.damp(a.vx||0,0,14,dt);a.vz=gameplay.damp(a.vz||0,0,14,dt);a.anim=a._activityAnim||a.anim||'idle';a.rig.position.set(a.x,a.y,a.z);a.rig.rotation.y=a.yaw;input.jumpQueued=false;return}}gameplay.smoothVelocity(a,intent,sprint?preset.runSpeed:preset.walkSpeed,dt,{accel:preset.groundAccel,brake:preset.groundBrake,airControl:preset.airControl});gameplay.updateJumpMemory(a,dt,input.jumpQueued);const jumped=gameplay.consumeBufferedJump(a,preset.jumpSpeed);gameplay.applyVariableJump(a,input.jumpHeld||game.padJumpHeld);const jumpRequest=(a._jumpBuffer||0)>0||jumped;const r=move.attemptCharacterMove(a,a.vx*dt,a.vz*dt,game.world.colliders,{radius:a.radius,height:a.height,maxStep:.4,maxMantle:isDog(a.person)?.78:1.05,jumpRequested:jumpRequest});input.jumpQueued=false;let nx=r.x,nz=r.z;if(r.mantle){a.y=r.mantle.targetY+.02;a.vy=2.15;a.grounded=false;a.anim='mantle'}if(game.zone==='island'&&Math.hypot(nx,nz)>51.3){nx=a.x;nz=a.z;a.vx*=.2;a.vz*=.2}a.x=clamp(nx,game.world.bounds.minX,game.world.bounds.maxX);a.z=clamp(nz,game.world.bounds.minZ,game.world.bounds.maxZ);if(r.y>a.y)a.y=r.y;a.vy-=preset.gravity*dt;const nextY=a.y+a.vy*dt,ceil=a.vy>0?move.ceilingBottom(a.x,a.z,a.radius,a.y,a.height,nextY,game.world.colliders):null;if(ceil!=null){a.y=ceil-a.height-.015;a.vy=0}else a.y=nextY;const support=Math.max(game.world.groundHeight?.(a.x,a.z)||0,move.supportHeight(a.x,a.z,a.radius,game.world.colliders,a.y+.08,.42));if(a.y<=support){if(a.vy<-.8)a.landTimer=.12;a.y=support;a.vy=0;a.grounded=true}else a.grounded=false;a.landTimer=Math.max(0,(a.landTimer||0)-dt);const moving=Math.hypot(a.vx,a.vz)>.16;if(moving){const desired=Math.atan2(a.vx,-a.vz),old=a.yaw;a.yaw=gameplay.dampAngle(a.yaw,desired,13,dt);let d=a.yaw-old;while(d>Math.PI)d-=Math.PI*2;while(d<-Math.PI)d+=Math.PI*2;a.turnRate=d/Math.max(dt,.001)}else a.turnRate=gameplay.damp(a.turnRate||0,0,8,dt);if(!moving)gameplay.updateContextFacing(a,dt);a.anim=gameplay.resolveLocomotionAnim(a,{moving,sprinting:sprint,mantling:!!r.mantle});a.rig.position.set(a.x,a.y,a.z);a.rig.rotation.y=a.yaw;a.zone=game.zone;a.homeOwnerId=game.homeOwnerId;resolveActorOverlap(a)}
function updateCamera(dt){const a=game.player;if(!a)return;if(gameplay.recoverActorFromGeometry(move,a,game.world.colliders,game.world.bounds,{radius:a.radius,height:a.height,maxRadius:4.5,groundAt:game.zone==='island'?game.world.groundHeight:null})){game.stagingQa?.setRecovery('player geometry recovery');game.cameraRig.reset(a,game.world.colliders,{yaw:a.yaw,pitch:.06,distance:game.zone==='home'?3.9:game.cameraRig.state.targetDistance||game.cameraRig.cfg.cameraDistance,dog:isDog(a.person),height:isDog(a.person)?.64:1.14,forceSnap:true,reason:'player geometry recovery'});}const sprinting=gameplay.wantsSprint(keys,input,game.padButtons||{},{strength:Math.min(1,Math.hypot(a.vx,a.vz)/(game.cameraRig.cfg.runSpeed||1))});game.cameraRig.update(a,game.world.colliders,dt,{dog:isDog(a.person),height:isDog(a.person)?.64:1.14,sprinting,velocity:{x:a.vx,z:a.vz},turnRate:a.turnRate||0,cameraBob:(a._motion?.landing||0)*-.022});game.cameraYaw=game.cameraRig.state.yaw;game.cameraPitch=game.cameraRig.state.pitch;game.cameraDistance=game.cameraRig.state.actualDistance;for(const r of game.world.roofs){const inside=Math.abs(a.x-r.x)<r.w/2-.2&&Math.abs(a.z-r.z)<r.d/2-.2;r.mesh.material.opacity=inside?.08:1;r.mesh.visible=!inside||game.cameraDistance<3.7}}
function interactionLineOfSight(item){if(!game?.player||!item)return false;const a=game.player,eyeY=a.y+(isDog(a.person)?.62:Math.min(1.35,a.height*.72)),origin={x:a.x,y:eyeY,z:a.z},target={x:item.x,y:eyeY,z:item.z},colliders=(game.world?.colliders||[]).filter(c=>!(Math.abs(item.x-c.x)<=c.w/2+.18&&Math.abs(item.z-c.z)<=c.d/2+.18));return move.lineOfSightClear(origin,target,colliders,.08)}
function detectInteraction(){if(!game?.player)return;const candidate=gameplay.chooseInteraction(game.player,game.world.interactions,{radius:3.15,yaw:game.cameraYaw}),best=candidate&&interactionLineOfSight(candidate)?candidate:null;game.nearby=best;const el=root.querySelector('#ilInteract'),btn=root.querySelector('#ilInteractBtn');if(el){el.classList.toggle('show',!!best);el.textContent=best?best.label:''}if(btn){const label=best?.label||'USE';btn.textContent=String(label).replace(/^(Open|Enter|Visit|Use)\s+/i,'').slice(0,14).toUpperCase();btn.disabled=!best;btn.classList.toggle('ready',!!best)}}
function updateDayNight(dt=.016,nowMs=performance.now()){if(!state||!game||game.zone!=='island')return;const worldTime=Date.now(),progress=((worldTime-(state.dayAnchor||worldTime))%(state.dayLengthMs||1200000))/(state.dayLengthMs||1200000),ang=progress*Math.PI*2-Math.PI/2,day=Math.max(.08,Math.sin(ang)*.5+.5),sun=game.lights.sun;sun.position.set(Math.cos(ang)*35,6+day*34,Math.sin(ang)*28);const weather=game.weather?.update(dt,worldTime,game.player)||{cloud:0,rain:0,wind:.2,exposure:1};const baseSun=.4+day*2.2,baseHemi=.45+day*.95;sun.intensity=baseSun*(1-(weather.cloud||0)*.55);game.lights.hemi.intensity=baseHemi*(1-(weather.cloud||0)*.22);const nightC=new THREE.Color(0x172c46),dayC=new THREE.Color(0x78bdc9),stormC=new THREE.Color(0x5f7480);game.scene.background.copy(nightC).lerp(dayC,day).lerp(stormC,(weather.cloud||0)*.32);if(game.scene.fog)game.scene.fog.color.copy(game.scene.background);game.renderer.toneMappingExposure=(.72+day*.4)*(weather.exposure||1);game.nightFactor=1-day;if(game.world.water)studio.animateWater(game.world.water,nowMs*.001,weather.wind||.2);audio.setAmbience({rain:weather.rain||0,wind:weather.wind||0,water:.4,birds:weather.rain>.3?.05:.35});game.weatherState=weather}
function sendSnapshot(force=false){if(!game?.player||!ws||ws.readyState!==1)return;const t=performance.now();if(!force&&t-game.lastSnapshot<90)return;game.lastSnapshot=t;const a=game.player;ws.send(JSON.stringify({type:'snapshot',snapshot:{x:a.x,y:a.y,z:a.z,yaw:a.yaw,pitch:game.cameraRig?.state?.pitch??game.cameraPitch,vx:a.vx,vy:a.vy,vz:a.vz,anim:a.anim,zone:game.zone,homeOwnerId:game.homeOwnerId,seq:Math.floor(t)}}))}
function connectWs(){clearTimeout(reconnectTimer);try{if(ws){ws.onclose=null;ws.close()}}catch(err){console.warn('Island WebSocket reset failed',err)}if(pageDisposed)return;const proto=location.protocol==='https:'?'wss:':'ws:';ws=new WebSocket(`${proto}//${location.host}/api/island/ws?room=${encodeURIComponent(roomId)}&token=${encodeURIComponent(playerToken)}`);ws.onmessage=e=>{let m;try{m=JSON.parse(e.data)}catch(err){console.warn('Island WebSocket message parse failed',err);return}if(m.type==='state')syncState(m.state);if(m.type==='snapshot'){const a=game?.actors?.get(m.playerId);if(a&&!a.isLocal){a.netBuffer?.push(m.snapshot,performance.now());a.netTarget=m.snapshot}}if(m.type==='action'&&m.action==='emote'){const a=game?.actors?.get(m.playerId);if(a)gameplay.playTransientAnimation(a,m.emote==='wave'?'wave':m.emote,1800)}};ws.onclose=()=>{if(!pageDisposed)reconnectTimer=setTimeout(()=>state&&connectWs(),1800)}}
function syncState(n){const prev=state;state=n;if(!game)return;const me=n.viewer;if(me&&game.player){game.player.resident=me;game.player.person=personById(me.avatar)}rebuildWorld(false);syncActors(false);for(const a of game.actors.values())a.rig.visible=a.zone===game.zone&&(a.zone!=='home'||a.homeOwnerId===game.homeOwnerId);renderHud();renderPhoneIfOpen();if(prev?.revision!==n.revision)applyCooldownVisibility(game.world)}
async function fetchAndMaybeSync(){try{const n=await fetchState();syncState(n)}catch(e){toast(e.message)}}
function nudgeLoosePhysics(){if(!game?.player||!game.physics)return;const a=game.player,speed=Math.hypot(a.vx||0,a.vz||0);if(speed<.22)return;for(const b of game.physics.bodies){const dx=b.mesh.position.x-a.x,dz=b.mesh.position.z-a.z,d=Math.hypot(dx,dz),min=(a.radius||.33)+b.radius+.12;if(d>0&&d<min&&performance.now()>(b._playerTouchAt||0)){b._playerTouchAt=performance.now()+180;const scale=.48+speed*.2;game.physics.impulse(b,{x:dx/d*scale,y:.08,z:dz/d*scale});b.spin.x+=(a.vz||0)*.12;b.spin.z-=(a.vx||0)*.12;audio.oneShot('impact',{volume:.025,pitch:1.1+Math.random()*.18,pan:studio.computeStereoPan(game.cameraYaw,a,b.mesh.position)})}}}
function loop(nowMs){if(!game)return;const dt=Math.min(.045,Math.max(.001,(nowMs-lastFrame)/1000));lastFrame=nowMs;gameplay.applyGamepadLook(game.cameraRig.state,dt);const pad=gameplay.readGamepadButtons();if(pad.jump&&!game.padPrev.jump)input.jumpQueued=true;if(pad.shoulder&&!game.padPrev.shoulder)game.cameraRig?.swapShoulder();if(pad.interact&&!game.padPrev.interact)triggerInteraction();game.padSprint=pad.sprint;game.padJumpHeld=pad.jump;game.padButtons=pad;game.padPrev=pad;game.cameraYaw=game.cameraRig.state.yaw;game.cameraPitch=game.cameraRig.state.pitch;movePlayer(dt);updateCamera(dt);detectInteraction();animateActors(dt);updateDayNight(dt,nowMs);sendSnapshot();renderHudThrottled();if(QA_MODE)updateQaHud(dt,nowMs);game.stagingQa?.update(dt,nowMs);game.performance?.sample(dt);game.motionFx?.update(dt);nudgeLoosePhysics();game.physics?.update(dt);game.cinematic?.update(dt);audio.update(dt);if(game.world?.group)art.animateAmbience(game.world.group,nowMs*.001,{player:game.player,dt,nightFactor:game.nightFactor??0});game.renderer.render(game.scene,game.camera);raf=requestAnimationFrame(loop)}
function updateQaHud(dt,now){const q=game?.qa,a=game?.player,el=root.querySelector('#ilQa');if(!q||!a||!el)return;q.frames++;q.accum+=dt;if(q.accum>=.5){q.fps=Math.round(q.frames/q.accum);q.frames=0;q.accum=0}if(now-(q.lastHud||0)<250)return;q.lastHud=now;const info=game.renderer.info.render;el.textContent=[`QA · ${game.zone} · ${q.fps||'--'} fps`,`pos ${a.x.toFixed(2)}, ${a.y.toFixed(2)}, ${a.z.toFixed(2)}  yaw ${a.yaw.toFixed(2)}`,`grounded ${a.grounded?'yes':'no'}  camera ${game.cameraRig.state.actualDistance.toFixed(2)}  recoveries ${game.cameraRig.state.recoveries}`,`colliders ${game.world.colliders.length}  draw ${info.calls}  tris ${info.triangles}`].join('\n')}
let lastHud=0;function renderHudThrottled(){const t=performance.now();if(t-lastHud>500){lastHud=t;renderHud()}}
function projectedUiNeeds(){if(!state?.viewer)return{energy:100,hunger:100,fun:100,social:100};return life.projectedNeeds(state.viewer)}
function jobName(id){return id&&life.JOBS[id]?life.JOBS[id].name:'No job yet'}
function renderHud(){if(!state?.viewer||!game)return;const v=state.viewer,n=projectedUiNeeds(),time=((Date.now()-(state.dayAnchor||Date.now()))%(state.dayLengthMs||1200000))/(state.dayLengthMs||1200000),mins=Math.floor(time*24*60),hh=String(Math.floor(mins/60)).padStart(2,'0'),mm=String(mins%60).padStart(2,'0'),zone=game.zone==='home'?`${currentHomeOwner()?.name||'Family'}'s Home`:'Island';const hud=root.querySelector('#ilHud'),needs=root.querySelector('#ilNeeds');if(!hud||!needs)return;hud.innerHTML=`<div class="il-hud-left"><span class="il-pill"><strong>${money(v.money)}</strong> Island Cash</span><span class="il-pill job">${esc(jobName(v.job))}</span><span class="il-pill">${esc(zone)}</span></div><div class="il-hud-right"><span class="il-pill">${esc((game.weatherState?.state||'sunny').replace(/^./,c=>c.toUpperCase()))}</span><span class="il-pill">${hh}:${mm}</span><button id="ilHomeLodge">⌂ Lodge</button></div>`;hud.querySelector('#ilHomeLodge').onclick=()=>location.href='/';needs.innerHTML=Object.entries({energy:['Energy',n.energy],hunger:['Food',n.hunger],fun:['Fun',n.fun],social:['Social',n.social]}).map(([,d])=>`<div class="il-need"><span>${d[0]}</span><span class="il-bar"><i style="width:${Math.round(d[1])}%"></i></span><b>${Math.round(d[1])}</b></div>`).join('')}
function panelHead(title,sub){return `<div class="il-panel-head"><h2>${esc(title)}</h2><p>${esc(sub)}</p></div>`}
function inventoryPanel(v){const rows=Object.entries(v.inventory||{}).filter(([,q])=>q>0);return `${panelHead('Inventory','Gather resources, buy supplies and carry furniture home.')}<div class="il-grid">${rows.length?rows.map(([id,q])=>{const it=life.ITEMS[id];return `<article class="il-tile"><h3>${esc(it?.name||id)}</h3><span class="il-badge">x${q}</span><p>${esc(it?.type||'item')}</p>${it?.needs?`<button class="il-primary" data-consume="${id}">Use / Eat</button>`:''}</article>`}).join(''):'<div class="il-tile"><h3>Your backpack is empty.</h3><p>Explore the forest, meadow, rocky cove, beach and shops.</p></div>'}</div>`}
function jobsPanel(v){return `${panelHead('Jobs','Pick a job, then visit that workplace in the 3D island to work a shift.')}<div class="il-grid">${Object.entries(life.JOBS).map(([id,j])=>`<article class="il-tile"><h3>${esc(j.name)}</h3><p>${esc(j.description)}</p><span class="il-badge">Base pay ${money(j.pay)}</span><p>Skill XP: ${v.skills?.[j.skill]||0}</p><button class="${v.job===id?'il-secondary':'il-primary'}" data-job="${id}">${v.job===id?'Current Job':'Take Job'}</button></article>`).join('')}</div>`}
function materialList(m={}){return Object.entries(m).map(([id,q])=>`${q} ${life.ITEMS[id]?.name||id}`).join(' · ')||'No materials'}
function housePanel(v){if(!v.home)return `${panelHead('My Home','Walk to any VACANT HOME LOT sign around the residential coast and claim it.')}<div class="il-tile"><h3>No home lot yet.</h3><p>There are 13 persistent family lots around the coast, so everyone can have their own place.</p></div>`;const h=life.HOUSE_LEVELS[v.home.level||0],next=life.HOUSE_LEVELS[(v.home.level||0)+1],ownInside=game.zone==='home'&&game.homeOwnerId===v.id;return `${panelHead('My Home',`${h.name} · ${life.LOT_BY_ID[v.home.lotId]?.label||v.home.lotId}`)}<div class="il-grid"><article class="il-tile"><h3>${esc(h.name)}</h3><p>${esc(h.description)}</p><span class="il-badge">${h.rooms} room${h.rooms===1?'':'s'} · ${h.storage} storage</span>${next?`<h4>Next: ${esc(next.name)}</h4><p>${money(next.price)} + ${esc(materialList(next.materials))}</p><button class="il-primary" data-upgrade-house>Upgrade Home</button>`:'<div class="il-price">Fully upgraded</div>'}</article><article class="il-tile"><h3>Exterior</h3><p>Change the whole look of your house.</p>${['tropical','cabin','modern','beach'].map(x=>`<button class="${(v.home.style?.exterior||'tropical')===x?'il-secondary':'il-soft'}" data-exterior="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</article><article class="il-tile"><h3>Interior finishes</h3><p>Changing floor/wall finishes costs $90.</p><label class="il-field"><span>Floor</span><select id="ilFloor">${['pine','darkwood','sandstone','white-tile','slate'].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label><label class="il-field"><span>Walls</span><select id="ilWall">${['cream','sage','ocean','sunset','white','charcoal'].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label><button class="il-primary" data-home-style>Apply Finish</button></article><article class="il-tile"><h3>Decorate</h3><p>Buy or craft furniture, enter your own home, then place it wherever you want.</p><button class="${ownInside?'il-primary':'il-soft'}" data-decorate ${ownInside?'':'disabled'}>${ownInside?'Open Decorate Mode':'Go inside your home first'}</button></article></div>`}
function wardrobePanel(v){return `${panelHead('Wardrobe','Clothes bought at Drift Boutique stay in your wardrobe permanently.')}<div class="il-grid"><article class="il-tile"><h3>Original outfit</h3><button class="${!v.equippedClothing?'il-secondary':'il-soft'}" data-outfit="">Wear</button></article>${(v.wardrobe||[]).map(id=>`<article class="il-tile"><h3>${esc(life.ITEMS[id]?.name||id)}</h3><button class="${v.equippedClothing===id?'il-secondary':'il-primary'}" data-outfit="${id}">${v.equippedClothing===id?'Wearing':'Wear'}</button></article>`).join('')}</div>`}
function craftingPanel(v){return `${panelHead('Crafting','Gather supplies, then visit the Island Workshop to craft furniture and food.')}<div class="il-grid">${Object.entries(life.RECIPES).map(([id,r])=>`<article class="il-tile"><h3>${esc(r.name)}</h3><p>${esc(materialList(r.materials))}</p><button class="il-primary" data-craft="${id}">Craft</button></article>`).join('')}</div>`}
function mapPanel(){const mapPos=(x,z)=>({left:`${50+x/1.15}%`,top:`${50+z/1.15}%`}),points=[...Object.values(life.BUILDINGS).filter(b=>b.name!=='Island Plaza').map(b=>({label:b.name,x:b.x,z:b.z})),...(state.residents||[]).filter(r=>r.home).map(r=>{const l=life.LOT_BY_ID[r.home.lotId];return{label:r.name,x:l.x,z:l.z,home:true}})];return `${panelHead(state.islandName,'Stores in the middle, wild resource districts around them, family homes around the coast.')}<div class="il-map">${points.map(p=>{const pos=mapPos(p.x,p.z);return `<span class="il-map-dot ${p.home?'home':''}" style="left:${pos.left};top:${pos.top}"></span><span class="il-map-label" style="left:${pos.left};top:calc(${pos.top} + 14px)">${esc(p.label)}</span>`}).join('')}</div><p>Forest to the west · meadow and gardens northeast · rocky cove south · marina southeast · residential coast around the island.</p>`}
function residentsPanel(){return `${panelHead('Island Residents','Visit each other, walk into each other’s homes and build the island together.')}<div class="il-grid">${state.residents.map(r=>`<article class="il-tile il-resident"><img src="${avatarThumb(r.avatar)}" onerror="this.style.visibility='hidden'" alt=""><div><h3>${esc(r.name)}</h3><span class="${r.connected?'online':'offline'}">${r.connected?'● Online':'○ Offline'}</span><p>${r.job?esc(jobName(r.job)):'Island resident'}${r.home?` · ${esc(life.LOT_BY_ID[r.home.lotId]?.label||'Home')}`:' · Looking for a home'}</p></div></article>`).join('')}</div>`}
function profilePanel(v){return `${panelHead('My Character','Use the same all-angle 3D family cast as our other 3D games.')}<label class="il-field"><span>Name</span><input id="ilProfileName" maxlength="24" value="${esc(v.name)}"></label><div class="il-character-grid">${family.map(p=>`<button class="il-character-button ${v.avatar===p.id?'selected':''}" data-profile-avatar="${p.id}"><img src="${avatarThumb(p.id)}" onerror="this.style.visibility='hidden'" alt=""><span>${esc(p.name)}</span></button>`).join('')}</div><button class="il-primary" data-save-profile>Save Character</button>${state.isHost?`<hr><label class="il-field"><span>Island name</span><input id="ilIslandName" maxlength="32" value="${esc(state.islandName)}"></label><button class="il-secondary" data-rename-island>Rename Island</button>`:''}`}
function phonePanel(){const v=state.viewer;if(phoneTab==='inventory')return inventoryPanel(v);if(phoneTab==='jobs')return jobsPanel(v);if(phoneTab==='house')return housePanel(v);if(phoneTab==='wardrobe')return wardrobePanel(v);if(phoneTab==='crafting')return craftingPanel(v);if(phoneTab==='map')return mapPanel();if(phoneTab==='residents')return residentsPanel();return profilePanel(v)}
function closeOverlay(){root.querySelector('.il-overlay')?.remove();overlayOpen=false}
function renderPhone(){if(!state?.viewer)return;closeOverlay();overlayOpen=true;const o=document.createElement('div');o.className='il-overlay';const tabs=[['inventory','Inventory'],['jobs','Jobs'],['house','My Home'],['wardrobe','Wardrobe'],['crafting','Crafting'],['map','Map'],['residents','Residents'],['profile','Profile']];o.innerHTML=`<button class="il-close" aria-label="Close">×</button><div class="il-phone"><nav class="il-phone-nav">${tabs.map(([id,l])=>`<button data-phone-tab="${id}" class="${phoneTab===id?'active':''}">${l}</button>`).join('')}</nav><section class="il-phone-body">${phonePanel()}</section></div>`;root.append(o);o.querySelector('.il-close').onclick=closeOverlay;o.addEventListener('click',e=>{if(e.target===o)closeOverlay()});o.querySelectorAll('[data-phone-tab]').forEach(b=>b.onclick=()=>{phoneTab=b.dataset.phoneTab;renderPhone()});bindPhoneActions(o)}
function renderPhoneIfOpen(){if(overlayOpen&&root.querySelector('.il-phone'))renderPhone()}
function bindPhoneActions(o){o.querySelectorAll('[data-consume]').forEach(b=>b.onclick=async()=>{try{const itemId=b.dataset.consume,item=life.ITEMS[itemId];await act('consume',{itemId});if(game?.player){const liquid=/coffee|latte|smoothie|drink|tea|juice/i.test(`${itemId} ${item?.name||''}`);gameplay.playTransientAnimation(game.player,liquid?'drink':'eat',liquid?1150:1250);audio.oneShot(liquid?'coffee':'ui',{volume:.04,pitch:liquid?1.0:.72})}}catch{}});o.querySelectorAll('[data-job]').forEach(b=>b.onclick=async()=>{try{await act('setJob',{job:b.dataset.job});toast(`You are now a ${jobName(b.dataset.job)}.`)}catch{}});o.querySelector('[data-upgrade-house]')?.addEventListener('click',async()=>{try{const d=await act('upgradeHouse');toast(`House upgraded to ${d.name}!`);game.cinematic?.start({duration:1.8,distance:6.4,pitch:.27,yawOffset:.8})}catch{}});o.querySelectorAll('[data-exterior]').forEach(b=>b.onclick=async()=>{try{await act('houseExterior',{exterior:b.dataset.exterior})}catch{}});const f=o.querySelector('#ilFloor'),w=o.querySelector('#ilWall');if(f&&state.viewer.home)f.value=state.viewer.home.style?.floor||'pine';if(w&&state.viewer.home)w.value=state.viewer.home.style?.wall||'cream';o.querySelector('[data-home-style]')?.addEventListener('click',async()=>{try{await act('homeStyle',{floor:f.value,wall:w.value})}catch{}});o.querySelector('[data-decorate]')?.addEventListener('click',()=>{closeOverlay();openBuildMode()});o.querySelectorAll('[data-outfit]').forEach(b=>b.onclick=async()=>{try{await act('equipClothing',{itemId:b.dataset.outfit||null})}catch{}});o.querySelectorAll('[data-craft]').forEach(b=>b.onclick=async()=>{try{const d=await act('craft',{recipeId:b.dataset.craft});toast(`Crafted ${life.ITEMS[d.itemId]?.name||d.itemId}.`)}catch{}});let profileAvatar=state.viewer.avatar;o.querySelectorAll('[data-profile-avatar]').forEach(b=>b.onclick=()=>{profileAvatar=b.dataset.profileAvatar;o.querySelectorAll('[data-profile-avatar]').forEach(x=>x.classList.toggle('selected',x===b))});o.querySelector('[data-save-profile]')?.addEventListener('click',async()=>{const name=o.querySelector('#ilProfileName').value.trim()||state.viewer.name;try{await post('profile',{playerToken,name,avatar:profileAvatar});localStorage.setItem('gn_name',name);await fetchAndSync();toast('Character updated.')}catch(e){toast(e.message)}});o.querySelector('[data-rename-island]')?.addEventListener('click',async()=>{try{await act('renameIsland',{name:o.querySelector('#ilIslandName').value,hostToken});toast('Island renamed.')}catch{}})}
function openPhone(tab='inventory'){phoneTab=tab;renderPhone()}
function storeItems(id){return Object.entries(life.ITEMS).filter(([,i])=>i.store===id&&i.buy>0)}
function openStore(id){closeOverlay();overlayOpen=true;const b=life.BUILDINGS[id],o=document.createElement('div');o.className='il-overlay';o.innerHTML=`<button class="il-close">×</button><section class="il-store"><div class="il-panel-head"><h2>${esc(b?.name||'Shop')}</h2><p>You have ${money(state.viewer.money)}.</p></div>${storeItems(id).map(([itemId,it])=>`<div class="il-store-row"><div><b>${esc(it.name)}</b><div style="font-size:11px;color:#60706c">${esc(it.type)}</div></div><strong>${money(it.buy)}</strong><button class="il-primary" data-buy="${itemId}">Buy</button></div>`).join('')||'<p>No retail items at this counter.</p>'}${id==='market'?`<h3>Sell from backpack</h3>${Object.entries(state.viewer.inventory||{}).filter(([item,q])=>q>0&&life.ITEMS[item]?.sell).map(([item,q])=>`<div class="il-store-row"><div><b>${esc(life.ITEMS[item].name)}</b> x${q}</div><strong>${money(life.ITEMS[item].sell)}</strong><button class="il-soft" data-sell="${item}">Sell One</button></div>`).join('')}`:''}</section>`;root.append(o);o.querySelector('.il-close').onclick=closeOverlay;o.querySelectorAll('[data-buy]').forEach(x=>x.onclick=async()=>{try{await act('buy',{store:id,itemId:x.dataset.buy});audio.oneShot('ui',{volume:.035,pitch:1.35});openStore(id)}catch{}});o.querySelectorAll('[data-sell]').forEach(x=>x.onclick=async()=>{try{await act('sell',{itemId:x.dataset.sell,qty:1});audio.oneShot('ui',{volume:.03,pitch:.82});openStore(id)}catch{}})}
function furnitureUseOptions(i){const kind=i?.furnitureKind||life.ITEMS[i?.itemId]?.kind||'';const table={bed:[['sit','Sit on Bed'],['sleep','Sleep']],chair:[['sit','Sit']],sofa:[['sit','Sit'],['relax','Relax']],hammock:[['relax','Relax']],tv:[['watch','Watch TV']],fridge:[['use','Open Fridge']],stove:[['cook','Cook']],sink:[['wash','Wash Up']],dresser:[['wardrobe','Change Clothes']],toilet:[['use','Use']],tub:[['bathe','Bathe']],desk:[['sit','Sit'],['work','Use Desk']],table:[['sit','Sit']],counter:[['use','Use Counter']],lamp:[['light','Toggle Light']],bookshelf:[['use','Browse Books']],art:[['use','Inspect']],rug:[['use','Inspect']],plant:[['use','Inspect']]};return table[kind]||[['use','Use']]}
function furnitureAnim(use){return({sit:'sit',relax:'sit',watch:'sit',bathe:'sit',sleep:'sleep',cook:'cook',wash:'use',work:'work',wardrobe:'inspect',light:'use',use:'use'}[use]||'use')}
async function useFurnitureInteraction(i,use){try{const d=await act('useFurniture',{pieceId:i.pieceId,use});const dur=use==='sleep'?4200:use==='relax'||use==='watch'||use==='bathe'?2400:1500;gameplay.playContextAnimation(game.player,furnitureAnim(use),i,dur);game.player._activityUntil=performance.now()+dur;game.player._activityAnim=furnitureAnim(use);if(use==='wardrobe')setTimeout(()=>openPhone('wardrobe'),250);if(use==='sleep')toast('You settle in and wake up rested.');else if(use==='watch')toast('A little TV time boosts Fun.');else if(use==='cook')toast('You make something warm to eat.');else if(use==='bathe')toast('Fresh, warm and recharged.');else if(use==='relax')toast('You take a well-earned break.');else if(use==='light')toast('Light toggled.');return d}catch{return null}}
function openFurnitureInteraction(i){closeOverlay();overlayOpen=true;const owner=currentHomeOwner(),mine=owner?.id===state.viewerId,item=life.ITEMS[i.itemId],uses=furnitureUseOptions(i).filter(([use])=>!(use==='sleep'&&!mine)),o=document.createElement('div');o.className='il-overlay';o.innerHTML=`<section class="il-modal"><h2>${esc(item?.name||'Furniture')}</h2><p>${mine?'Use it, or pick it up when you want to redecorate.':`You're visiting ${esc(owner?.name||'a family member')}'s home.`}</p><div class="il-grid">${uses.map(([use,label])=>`<button class="il-primary" data-furniture-use="${use}">${esc(label)}</button>`).join('')}${mine?'<button class="il-danger" id="ilPickup">Pick Up</button>':''}<button class="il-soft" id="ilCancel">Close</button></div></section>`;root.append(o);o.querySelectorAll('[data-furniture-use]').forEach(b=>b.onclick=async()=>{const use=b.dataset.furnitureUse;o.remove();overlayOpen=false;await useFurnitureInteraction(i,use)});o.querySelector('#ilPickup')?.addEventListener('click',async()=>{try{await act('removeFurniture',{pieceId:i.pieceId});o.remove();overlayOpen=false}catch{}});o.querySelector('#ilCancel').onclick=()=>{o.remove();overlayOpen=false}}
function furnitureInventory(){return Object.entries(state.viewer.inventory||{}).filter(([id,q])=>q>0&&life.ITEMS[id]?.type==='furniture')}
function openBuildMode(){if(game.zone!=='home'||game.homeOwnerId!==state.viewerId)return toast('Enter your own home first.');buildMode=true;buildSelected=furnitureInventory()[0]?.[0]||null;buildYaw=0;let bar=root.querySelector('.il-buildbar');if(!bar){bar=document.createElement('div');bar.className='il-buildbar';root.append(bar)}updateBuildBar()}
function updateBuildBar(){const bar=root.querySelector('.il-buildbar');if(!bar)return;const items=furnitureInventory();if(buildSelected&&!items.some(([id])=>id===buildSelected))buildSelected=null;bar.innerHTML=`<select id="ilBuildSelect"><option value="">Choose furniture</option>${items.map(([id,q])=>`<option value="${id}" ${buildSelected===id?'selected':''}>${esc(life.ITEMS[id].name)} · x${q}</option>`).join('')}</select><button class="il-soft" id="ilRotateBuild">Rotate</button><button class="il-primary" id="ilPlaceBuild">Place</button><button class="il-danger" id="ilCloseBuild">Done</button>`;bar.querySelector('#ilBuildSelect').onchange=e=>buildSelected=e.target.value||null;bar.querySelector('#ilRotateBuild').onclick=()=>buildYaw=(buildYaw+Math.PI/2)%(Math.PI*2);bar.querySelector('#ilPlaceBuild').onclick=placeBuild;bar.querySelector('#ilCloseBuild').onclick=()=>{buildMode=false;buildSelected=null;bar.remove()}}
async function placeBuild(){if(!buildSelected)return toast('Choose a furniture item first.');const a=game.player,forward={x:Math.sin(a.yaw),z:-Math.cos(a.yaw)},x=a.x+forward.x*1.5,z=a.z+forward.z*1.5;try{await act('placeFurniture',{itemId:buildSelected,x,z,yaw:buildYaw});toast(`${life.ITEMS[buildSelected].name} placed.`);updateBuildBar()}catch{}}
function enterHome(ownerId){const owner=state.residents.find(r=>r.id===ownerId);if(!owner?.home)return toast('Nobody lives here yet.');game.zone='home';game.homeOwnerId=ownerId;const b=life.houseInteriorBounds(owner.home.level);game.player.x=0;game.player.y=0;game.player.z=b.minZ+1.2;game.player.vx=game.player.vz=0;game.player.zone='home';game.player.homeOwnerId=ownerId;worldSig='';rebuildWorld(true);for(const a of game.actors.values())a.rig.visible=a===game.player||a.zone==='home'&&a.homeOwnerId===ownerId;sendSnapshot(true);resetPlayableView({announce:false});toast(`Entered ${owner.name}'s home.`)}
function exitHome(){const owner=currentHomeOwner(),lot=owner?.home?life.LOT_BY_ID[owner.home.lotId]:null;game.zone='island';game.homeOwnerId=null;game.player.x=lot?lot.x:0;game.player.z=lot?lot.z:16;game.player.y=0;game.player.zone='island';game.player.homeOwnerId=null;worldSig='';rebuildWorld(true);for(const a of game.actors.values())a.rig.visible=a.zone==='island'||a===game.player;sendSnapshot(true);resetPlayableView({announce:false});toast('Back outside.')}
function forageAnimationFor(node){if(!node)return'harvest';if(node.kind==='fish')return'cast';if(['wood','hardwood'].includes(node.kind))return'chop';if(node.kind==='stone')return'mine';if(node.kind==='clay')return'dig';return'harvest'}
function jobAnimationFor(job){return({barista:'work',shopkeeper:'work',carpenter:'work',ranger:'inspect',gardener:'water',fisher:'fish',stylist:'work',cook:'cook',courier:'carry'}[job]||'work')}
function playGatherSequence(node,target){const a=game.player,anim=forageAnimationFor(node);gameplay.playContextAnimation(a,anim,target,anim==='cast'?520:1200);if(anim==='cast')setTimeout(()=>gameplay.playContextAnimation(a,'reel',target,900),430);if(anim==='chop'||anim==='mine'||anim==='dig')audio.oneShot('impact',{volume:.055,pitch:anim==='mine'?.72:anim==='chop'?.88:1.05});if(anim==='cast')audio.oneShot('water',{volume:.04,pitch:.92})}
async function triggerInteraction(){const i=game?.nearby;if(!i)return;if(i.kind==='forage'){try{const d=await act('forage',{nodeId:i.nodeId});toast(`Found ${d.qty} ${life.ITEMS[d.itemId]?.name||d.itemId}`);const node=life.FORAGE_NODES.find(n=>n.id===i.nodeId);playGatherSequence(node,i)}catch{}return}if(i.kind==='store'){gameplay.playContextAnimation(game.player,gameplay.interactionAnimation(i.kind),i,720);openStore(i.id);return}if(i.kind==='craft'){gameplay.playContextAnimation(game.player,gameplay.interactionAnimation(i.kind),i,850);openPhone('crafting');return}if(i.kind==='workplace'){const jobs=Object.entries(life.JOBS).filter(([,j])=>j.building===i.id);if(state.viewer.job&&jobs.some(([id])=>id===state.viewer.job)){try{const d=await act('work');toast(`Shift complete: +${money(d.pay)}`);gameplay.playContextAnimation(game.player,jobAnimationFor(state.viewer.job),i,1450);audio.oneShot(state.viewer.job==='barista'?'coffee':'ui',{volume:.035,pitch:state.viewer.job==='barista'?1.0:.8})}catch{}}else openPhone('jobs');return}if(i.kind==='lot'){try{await act('claimLot',{lotId:i.lotId});toast('Home lot claimed. Your starter tent is up!');game.cinematic?.start({duration:1.2,distance:5.6,pitch:.09,yawOffset:.42})}catch{}return}if(i.kind==='home'){gameplay.playContextAnimation(game.player,'use',i,620);enterHome(i.ownerId);return}if(i.kind==='homeExit'){exitHome();return}if(i.kind==='furniture'){openFurnitureInteraction(i);return}if(i.kind==='plaza'){gameplay.playContextAnimation(game.player,gameplay.interactionAnimation(i.kind),i,820);openPhone('map')}}
function resetPlayableView({announce=true}={}){const a=game?.player;if(!a)return;const moved=gameplay.recoverActorFromGeometry(move,a,game.world.colliders,game.world.bounds,{radius:a.radius,height:a.height,maxRadius:5.5,groundAt:game.zone==='island'?game.world.groundHeight:null,requireCameraPocket:true,cameraHeight:isDog(a.person)?.64:1.14,cameraDistance:3.5,minCameraPocket:1.5});game.cameraRig.reset(a,game.world.colliders,{yaw:a.yaw,pitch:.06,distance:game.zone==='home'?Math.min(game.cameraRig.state.targetDistance||3.9,3.9):game.cameraRig.state.targetDistance||game.cameraRig.cfg.cameraDistance,dog:isDog(a.person),height:isDog(a.person)?.64:1.14,forceSnap:true,reason:'manual Reset View'});game.stagingQa?.setRecovery(moved?'manual Reset View + safe-position recovery':'manual Reset View');game.cameraYaw=game.cameraRig.state.yaw;game.cameraPitch=game.cameraRig.state.pitch;if(announce)toast(moved?'Moved you to a safe spot and reset the view.':'View reset behind your character.')}
function onKeyDown(e){keys[e.code]=true;if(e.code==='Space'){if(!e.repeat)input.jumpQueued=true;input.jumpHeld=true;e.preventDefault()}if(e.code==='KeyC'&&!e.repeat)game?.cameraRig?.swapShoulder();if(e.code==='KeyR'&&!e.repeat)resetPlayableView();if(e.code==='KeyE')triggerInteraction();if(e.code==='Tab'){e.preventDefault();openPhone()}if(e.code==='Escape'){closeOverlay();root.querySelector('.il-buildbar')?.remove();buildMode=false}}
function onKeyUp(e){keys[e.code]=false;if(e.code==='Space')input.jumpHeld=false}
function bindControls(){addEventListener('keydown',onKeyDown);addEventListener('keyup',onKeyUp);game.controlDisposers.push(()=>{removeEventListener('keydown',onKeyDown);removeEventListener('keyup',onKeyUp)});const canvas=root.querySelector('#ilCanvas');canvas.addEventListener('pointerdown',()=>audio.unlock(),{once:true});const j=root.querySelector('#ilJoy'),knob=j.querySelector('i');game.controlDisposers.push(gameplay.bindPointerLook(canvas,game.cameraRig,{ignoreSelector:'button,select,input,a,.il-mobile,.il-phone-button'}));game.controlDisposers.push(gameplay.bindVirtualJoystick(j,knob,joy,{deadzone:.09,travel:.35}));game.controlDisposers.push(gameplay.mountControlPreferences(canvas.closest('.il-stage'),game.cameraRig,{layoutTarget:canvas.closest('.il-stage'),top:'58px'}));game.controlDisposers.push(studio.mountAudioPreferences(canvas.closest('.il-stage'),audio,{top:'58px',right:'68px'}));const jump=root.querySelector('#ilJump');jump.onpointerdown=()=>{input.jumpQueued=true;input.jumpHeld=true};jump.onpointerup=jump.onpointercancel=()=>{input.jumpHeld=false};root.querySelector('#ilShoulder').onclick=()=>game.cameraRig.swapShoulder();root.querySelector('#ilResetView').onclick=()=>resetPlayableView();root.querySelector('#ilSprint').onclick=e=>{input.sprint=!input.sprint;e.currentTarget.classList.toggle('primary',input.sprint)};root.querySelector('#ilInteractBtn').onclick=triggerInteraction;root.querySelector('#ilPhone').onclick=()=>openPhone();root.querySelector('#ilEmote').onclick=async()=>{gameplay.playTransientAnimation(game.player,'wave',1500);try{await act('emote',{emote:'wave'})}catch{}}}
function disposeIslandClient(){pageDisposed=true;cancelAnimationFrame(raf);raf=0;clearInterval(pollTimer);pollTimer=null;clearTimeout(reconnectTimer);reconnectTimer=null;try{if(ws){ws.onclose=null;ws.close();ws=null}}catch(err){console.warn('Island WebSocket close failed',err)}if(game){for(const off of game.controlDisposers||[]){try{off?.()}catch(err){console.warn('Island control cleanup failed',err)}}disposeVisitors();for(const a of game.actors?.values?.()||[])disposeActor(a);game.actors?.clear?.();game.world?.dispose?.();game.weather?.dispose?.();game.physics?.clear?.();game.motionFx?.dispose?.();game.renderer?.dispose?.();game=null}}
addEventListener('pagehide',disposeIslandClient,{once:true});
async function bootResident(){pageDisposed=false;try{const s=await fetchState();if(!s.viewerId){playerToken=null;localStorage.removeItem(`gn_island_player_${roomId}`);renderJoin();return}state=s;initScene();syncState(s);connectWs();clearInterval(pollTimer);pollTimer=setInterval(fetchAndMaybeSync,5000)}catch(e){renderLoading('Could not open the island');toast(e.message)}}
if(!roomId){root.innerHTML=`<div class="il-join"><section class="il-card"><span class="il-eyebrow">BLACK FAMILY ISLAND LIFE</span><h1>Start from the Game Lodge.</h1><p>Create the persistent family island from the New Family Games shelf, then share its private invite link.</p><button class="il-primary" onclick="location.href='/'">Back to Game Lodge</button></section></div>`}else if(!playerToken)renderJoin();else{renderLoading();bootResident()}
